// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Priority_Arbitration_supervisor_process_priority_arbitration_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration)
  }

  /** helper function to set the values of all input ports.
   * @param emergency_state payload for data port emergency_state
   * @param mining_proposal payload for data port mining_proposal
   * @param defense_proposal payload for data port defense_proposal
   * @param mobility_proposal payload for data port mobility_proposal
   */
  def put_concrete_inputs(emergency_state : Mining_Threat_Retreat_Supervision.EmergencyStateValue,
                          mining_proposal : Mining_Threat_Retreat_Supervision.ProposalValue,
                          defense_proposal : Mining_Threat_Retreat_Supervision.ProposalValue,
                          mobility_proposal : Mining_Threat_Retreat_Supervision.MobilityProposalValue): Unit = {
    put_emergency_state(emergency_state)
    put_mining_proposal(mining_proposal)
    put_defense_proposal(defense_proposal)
    put_mobility_proposal(mobility_proposal)
  }


  /** helper function to check Priority_Arbitration_supervisor_process_priority_arbitration's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param selected_action method that will be called with the value of the outgoing data
   *        port 'selected_action'.
   * @param selected_cause method that will be called with the value of the outgoing data
   *        port 'selected_cause'.
   */
  def check_concrete_output(selected_action: Mining_Threat_Retreat_Supervision.ActionValue => B,
                            selected_cause: Mining_Threat_Retreat_Supervision.SelectedCauseValue => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val selected_actionValue: Mining_Threat_Retreat_Supervision.ActionValue = get_selected_action().get
    if(!selected_action(selected_actionValue)) {
      testFailures = testFailures :+ st"'selected_action' did not match expected: value of the outgoing data port is ${selected_actionValue}"
    }
    val selected_causeValue: Mining_Threat_Retreat_Supervision.SelectedCauseValue = get_selected_cause().get
    if(!selected_cause(selected_causeValue)) {
      testFailures = testFailures :+ st"'selected_cause' did not match expected: value of the outgoing data port is ${selected_causeValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_emergency_state(value : Mining_Threat_Retreat_Supervision.EmergencyStateValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.operational_api.emergency_state_Id, Mining_Threat_Retreat_Supervision.EmergencyStateValue_Payload(value))
  }

  // setter for in DataPort
  def put_mining_proposal(value : Mining_Threat_Retreat_Supervision.ProposalValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.operational_api.mining_proposal_Id, Mining_Threat_Retreat_Supervision.ProposalValue_Payload(value))
  }

  // setter for in DataPort
  def put_defense_proposal(value : Mining_Threat_Retreat_Supervision.ProposalValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.operational_api.defense_proposal_Id, Mining_Threat_Retreat_Supervision.ProposalValue_Payload(value))
  }

  // setter for in DataPort
  def put_mobility_proposal(value : Mining_Threat_Retreat_Supervision.MobilityProposalValue): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.operational_api.mobility_proposal_Id, Mining_Threat_Retreat_Supervision.MobilityProposalValue_Payload(value))
  }

  // getter for out DataPort
  def get_selected_action(): Option[Mining_Threat_Retreat_Supervision.ActionValue] = {
    val value: Option[Mining_Threat_Retreat_Supervision.ActionValue] = get_selected_action_payload() match {
      case Some(Mining_Threat_Retreat_Supervision.ActionValue_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port selected_action.  Expecting 'Mining_Threat_Retreat_Supervision.ActionValue_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervision.ActionValue]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_selected_action_payload(): Option[Mining_Threat_Retreat_Supervision.ActionValue_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.initialization_api.selected_action_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervision.ActionValue_Payload]]
  }

  // getter for out DataPort
  def get_selected_cause(): Option[Mining_Threat_Retreat_Supervision.SelectedCauseValue] = {
    val value: Option[Mining_Threat_Retreat_Supervision.SelectedCauseValue] = get_selected_cause_payload() match {
      case Some(Mining_Threat_Retreat_Supervision.SelectedCauseValue_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port selected_cause.  Expecting 'Mining_Threat_Retreat_Supervision.SelectedCauseValue_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervision.SelectedCauseValue]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_selected_cause_payload(): Option[Mining_Threat_Retreat_Supervision.SelectedCauseValue_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.initialization_api.selected_cause_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervision.SelectedCauseValue_Payload]]
  }

}
